#!/usr/bin/env python3
"""ob-plugin-fb-message-guardian-scan — lit la boîte Messenger via le DOM (ob-page),
détecte la session fermée, et produit un plan d'action JSON. Zéro token IA."""
import argparse, json, os, re, subprocess, sys, time
from datetime import datetime

PLUGIN_ID = "fb-message-guardian"
SETTINGS_PATH = os.path.expanduser("~/.config/open-bot/plugin-%s.json" % PLUGIN_ID)
RULES_PATH = os.path.expanduser("~/.config/open-bot/fb-message-guardian-rules.json")
STATE_DIR = os.path.expanduser("~/.open-bot/" + PLUGIN_ID)
STATE_PATH = os.path.join(STATE_DIR, "state.json")
INBOX_URL = "https://www.messenger.com/"
LOGIN_MARKERS = ("se connecter", "mot de passe", "adresse électronique", "find your account",
                 "s'inscrire", "créer un nouveau compte")
E2EE_PLACEHOLDER = "chiffrement"
PHOTO_HINTS = ("photo", "\U0001F4F7")  # aperçus Messenger : « a envoyé une photo » / 📷

def out(obj, code=0):
    print(json.dumps(obj, ensure_ascii=False))
    sys.exit(code)

def sh(cmd, timeout=120):
    try:
        return subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        return None

def page_read(session):
    p = sh(["ob-page", "--session", session, "read"])
    if not p or p.returncode != 0:
        return None
    try:
        return json.loads(p.stdout.strip().splitlines()[-1])
    except Exception:
        return None

def load_json(path, default):
    try:
        with open(path, encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return default

def save_state(state):
    os.makedirs(STATE_DIR, exist_ok=True)
    tmp = STATE_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(state, f, ensure_ascii=False, indent=1)
    os.replace(tmp, STATE_PATH)

def inbox_visible(page):
    return any(re.search(r"discussions?\s*·", (e.get("label") or "").lower())
               for e in page.get("elements", []))

def detect_login(page):
    labels = " | ".join(e.get("label", "") for e in page.get("elements", [])).lower()
    has_inbox = re.search(r"discussions\s*·", labels) is not None
    url = page.get("url", "")
    if has_inbox:
        return "ok", has_inbox
    if "login" in url or any(m in labels for m in LOGIN_MARKERS):
        return "not_logged_in", has_inbox
    if page.get("title", "").lower().startswith("messenger") and not has_inbox:
        return "dom_changed", has_inbox
    return "needs_user", has_inbox

def load_rules():
    rules = load_json(RULES_PATH, [])
    return [r for r in rules
            if r.get("enabled", True) and (r.get("reply") or r.get("notify") or r.get("save_photo_to"))]

def match_rule(rules, sender, preview):
    """La « personnalité » des réponses : première règle qui matche (priorité croissante), ou None."""
    pl = (preview or "").lower()
    sl = (sender or "").lower()
    has_photo = any(h in pl for h in PHOTO_HINTS)
    for r in sorted(rules, key=lambda x: (int(x.get("priority", 100)),)):
        rs = (r.get("sender") or "").strip().lower()
        if rs and rs not in sl:
            continue
        words = [w.strip().lower() for w in (r.get("contains") or []) if w and w.strip()]
        if words and not any(w in pl for w in words):
            continue
        if r.get("photo") and not has_photo:
            continue
        return r
    return None

def parse_rows(page):
    """Retourne [{name, preview, time, own, group}] à partir des paires lien + 'Autres options pour X'."""
    els = page.get("elements", [])
    rows = []
    last_link = None
    for e in els:
        label = (e.get("label") or "").strip()
        if e.get("role") == "link" and label:
            last_link = label
        elif e.get("role") == "button" and label.startswith("Autres options pour "):
            name = label[len("Autres options pour "):].strip()
            if last_link and name.lower() in last_link.lower():
                rows.append(parse_row(last_link, name))
            last_link = None
    return rows

TIMEY = re.compile(r"^(?:(?:il y a\s+)?[\dh]|hier|auj|lun|mar|mer|jeu|ven|sam|dim)", re.I)

def norm_preview(p):
    """Clé stable d'un aperçu : minuscule, queues temporelles volatiles retirées."""
    s = (p or "").lower()
    s = re.sub(r"\s*·\s*(?:il y a\s+)?[\dh]+\s*(?:min|h|j|sec|heures?|minutes?|jours?|secondes?)\.?$", "", s)
    s = re.sub(r"\s+", " ", s).strip(" ·.")
    return s

def parse_row(label, name):
    s, group, online = label, False, False
    if s.startswith("Discussion de groupe : "):
        group, s = True, s[len("Discussion de groupe : "):]
    for _ in range(3):
        before = s
        m = re.match(r"^(?:En ligne|Actif(?:·?ve)?)\s+", s)
        if m:
            online, s = True, s[m.end():]
        m = re.match(r"^il y a\s+(?:\d+|une?|quelques?)\s*(?:seconde?s?|min(?:ute)?s?|h(?:eures?)?|j(?:ours?)?)\s+", s)
        if m:
            s = s[m.end():]
        if s.startswith(name + " "):
            s = s[len(name) + 1:]
        elif s == name:
            s = ""
        if s == before:
            break
    t = None
    parts = s.rsplit(" · ", 1)
    if len(parts) == 2 and 1 <= len(parts[1]) <= 24 and not parts[1].endswith("."):
        tail = parts[1].strip()
        s = parts[0].strip()
        if TIMEY.match(tail):
            t = tail  # horodatage (« 8 h », « hier ») : hors de l'aperçu pour un dédoublonnage stable
        # sinon : invite d'action (« Répondre ? ») : retirée de l'aperçu, pas un horodatage
    own = s.startswith("Vous: ")
    if own:
        s = s[len("Vous: "):]
    return {"name": name, "preview": s.strip(), "time": t, "own": own, "group": group}

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--session", required=True)
    ap.add_argument("--force", action="store_true", help="rescan immédiat, ignore l'intervalle")
    ap.add_argument("--interval-override-seconds", type=float, default=None,
                    help="remplace l'intervalle configuré (utilisé par le watcher)")
    ap.add_argument("--thread", metavar="NOM", help="lire les derniers messages d'une conversation")
    args = ap.parse_args()

    settings = load_json(SETTINGS_PATH, {}).get("settings", {})
    state = load_json(STATE_PATH, {"conversations": {}, "sends": {}, "sent_log": [], "pending": [],
                                   "logout_notified_on": None, "last_scan": 0})
    now = time.time()

    if args.thread:
        out(read_thread(args.session, args.thread))

    interval_min = float(settings.get("check_interval_minutes", 15) or 15)
    min_age = interval_min * 60
    if args.interval_override_seconds is not None:
        min_age = max(60.0, args.interval_override_seconds)
    if not args.force and state.get("last_scan") and now - state["last_scan"] < min_age - 30:
        out({"status": "too_soon", "next_due_in_min": round((min_age - (now - state["last_scan"])) / 60, 1)})

    page = page_read(args.session)
    if page is None or "messenger.com" not in page.get("url", "") or not inbox_visible(page):
        nav = sh(["ob-nav", "--session", args.session, "--goal", INBOX_URL])
        navtxt = (nav.stdout or "") + (nav.stderr or "") if nav else ""
        if '"status":"needs_user"' in navtxt or '"status":"blocked"' in navtxt:
            out({"status": "needs_user", "detail": "navigation refusée, écran à rendre à l'utilisateur"}, 3)
        time.sleep(4)
        page = page_read(args.session)
        if page is None:
            out({"status": "error", "detail": "lecture impossible après navigation"}, 4)

    status, has_inbox = detect_login(page)
    if status != "ok":
        state["last_scan"] = now
        save_state(state)
        today = datetime.now().strftime("%Y-%m-%d")
        if status == "not_logged_in" and settings.get("notify_logout", "true") == "true":
            if state.get("logout_notified_on") != today:
                state["logout_notified_on"] = today
                save_state(state)
                notify("Session Facebook fermée", "Reconnecte-toi dans le navigateur du bureau pour réactiver le gardien.")
                out({"status": "not_logged_in", "notified": True, "detail": "utilisateur notifié"}, 3)
            out({"status": "not_logged_in", "notified": False, "detail": "rappel déjà envoyé aujourd'hui"}, 3)
        out({"status": status, "detail": "boîte Messenger illisible via le DOM"}, 3)

    rows = parse_rows(page)
    if not rows:
        out({"status": "dom_changed", "detail": "aucune conversation lisible : sélecteurs à réparer"}, 3)

    keywords = [k.strip().lower() for k in (settings.get("trigger_keywords") or "").split(",") if k.strip()]
    whitelist = [w.strip().lower() for w in (settings.get("whitelist") or "").split(",") if w.strip()]
    mode = settings.get("reply_mode", "hybride")
    rules = load_rules()
    cap = int(float(settings.get("daily_reply_cap", 20) or 20))
    h_start = int(float(settings.get("active_hours_start", 8) or 0))
    h_end = int(float(settings.get("active_hours_end", 21) or 23))
    hour = datetime.now().hour
    hours_ok = (h_start <= hour <= h_end) if h_start <= h_end else (hour >= h_start or hour <= h_end)
    today = datetime.now().strftime("%Y-%m-%d")
    sent_today = state.get("sends", {}).get(today, 0)

    plan = []
    for r in rows:
        if r["group"] or r["own"] or not r["preview"]:
            continue
        prev = r["preview"]
        if not prev or E2EE_PLACEHOLDER in prev[:80]:
            continue
        known = state["conversations"].get(r["name"], {})
        pkey = norm_preview(prev)
        known_key = known.get("pkey") or norm_preview(known.get("preview", ""))
        if known_key == pkey:
            # même message : rafraîchit l'horodatage vu, ne replanifie PAS
            known.update({"time": r["time"], "seen": today})
            continue
        if now - float(known.get("planned") or 0) < max(600.0, min_age):
            # l'aperçu a bougé mais le fil vient d'être planifié (bruit DOM, badge, aperçu
            # qui se stabilise) : absorbe sans replanifier — le prochain passage confira.
            known.update({"preview": prev, "pkey": pkey, "time": r["time"], "seen": today})
            continue
        state["conversations"][r["name"]] = {"preview": prev, "pkey": pkey, "time": r["time"],
                                             "seen": today, "planned": now}
        matched = next((k for k in keywords if k in prev.lower()), None)
        whitelisted = (not whitelist) or any(w in r["name"].lower() for w in whitelist)
        entry = {"sender": r["name"], "preview": prev[:160], "time": r["time"], "pkey": pkey,
                 "matched_keyword": matched, "action": None, "reason": None}

        # 1. La personnalité des réponses : une règle du carnet remplace le défaut.
        rule = match_rule(rules, r["name"], prev)
        if rule:
            entry["rule_id"] = rule.get("id")
            if rule.get("save_photo_to"):
                entry["route_photo"] = rule["save_photo_to"]
            if rule.get("reply"):
                entry["text"] = rule["reply"]
                # mêmes portes DURES que les réponses modèles : heures, plafond, mode, liste blanche
                if not hours_ok:
                    entry["action"], entry["reason"] = "notify", "hors heures actives"
                elif sent_today >= cap:
                    entry["action"], entry["reason"] = "notify", "plafond quotidien atteint (%d)" % cap
                elif settings.get("send_mode", "approbation") != "direct":
                    entry["action"], entry["reason"] = "draft", "mode approbation"
                elif not whitelisted:
                    entry["action"], entry["reason"] = "draft", "expéditeur hors liste blanche"
                else:
                    entry["action"] = "send:template"
            else:
                entry["action"] = "notify"
                entry["notify_text"] = rule.get("notify") or ""
        # 2. Sinon, le comportement par défaut (mots-clés / modèle / IA).
        else:
            if mode == "hybride":
                action = "template" if matched else "ai"
            elif mode == "ia":
                action = "ai"
            else:
                action = "template" if matched else "notify"
            if action in ("template", "ai"):
                if not hours_ok:
                    action, entry["reason"] = "notify", "hors heures actives"
                elif sent_today >= cap:
                    action, entry["reason"] = "notify", "plafond quotidien atteint (%d)" % cap
                elif settings.get("send_mode", "approbation") != "direct":
                    action = "draft"
                    entry["reason"] = "mode approbation"
                elif not whitelisted:
                    action = "draft"
                    entry["reason"] = "expéditeur hors liste blanche"
                else:
                    action = "send:" + action
            entry["action"] = action
        plan.append(entry)

    state["last_scan"] = now
    await_ai = [p for p in state.get("pending", []) if p.get("status") == "await_ai"]
    save_state(state)
    out({"status": "ok", "unread_folders": folder_counts(page), "sent_today": sent_today,
         "cap": cap, "hours_ok": hours_ok, "new": plan,
         "await_ai": len(await_ai), "pending": len(state.get("pending", []))})

def folder_counts(page):
    counts = {}
    for e in page.get("elements", []):
        m = re.match(r"^(Discussions|Marketplace|Demandes)\s*·\s*(\d+)\s*non lus", e.get("label", ""))
        if m:
            counts[m.group(1)] = int(m.group(2))
    return counts

def read_thread(session, name):
    """Clique la conversation NOM et extrait les derniers messages lisibles (pour rédaction IA)."""
    page = page_read(session)
    if page is None or "messenger.com" not in page.get("url", "") or not inbox_visible(page):
        sh(["ob-nav", "--session", session, "--goal", INBOX_URL]); time.sleep(4)
        page = page_read(session)
        if page is None:
            return {"status": "error", "detail": "page illisible"}
    target = None
    for e in page.get("elements", []):
        if e.get("role") == "link" and name.lower() in (e.get("label") or "").lower():
            target = e["id"]; break
    if not target:
        return {"status": "error", "detail": "conversation introuvable : " + name}
    sh(["ob-page", "--session", session, "click", target]); time.sleep(4)
    page = page_read(session)
    msgs = []
    for e in (page or {}).get("elements", []):
        m = re.match(r"^Saisir, Message envoyé à (.+?) par (.+?)(?: : (.*))?$", e.get("label", ""))
        if m:
            msgs.append({"when": m.group(1), "author": m.group(2), "text": (m.group(3) or "").strip()})
    return {"status": "ok", "thread": name, "messages": msgs[-12:]}

def notify(title, body):
    sh(["ob-plugin", "notify", PLUGIN_ID, title, body])

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""ob-plugin-fb-message-guardian-send — envoie une réponse dans une conversation Messenger.
Double porte : réglages (mode d'envoi, liste blanche, plafond, heures) vérifiés ici aussi.
Le tap se fait via ob-vnc (clic dans le composer, collage, Entrée) car le composer n'est pas
exposé dans l'arbre accessible retourné par ob-page."""
import argparse, json, os, re, subprocess, sys, time
from datetime import datetime

PLUGIN_ID = "fb-message-guardian"
SETTINGS_PATH = os.path.expanduser("~/.config/open-bot/plugin-%s.json" % PLUGIN_ID)
STATE_PATH = os.path.expanduser("~/.open-bot/%s/state.json" % PLUGIN_ID)
INBOX_URL = "https://www.messenger.com/"
SIDEBAR_W = 380

def out(obj, code=0):
    print(json.dumps(obj, ensure_ascii=False)); sys.exit(code)

def sh(cmd, timeout=120):
    try:
        return subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        return None

def page_read(session):
    p = sh(["ob-page", "--session", session, "read"])
    if not p or p.returncode != 0: return None
    try: return json.loads(p.stdout.strip().splitlines()[-1])
    except Exception: return None

def load():
    settings = {}
    try:
        with open(SETTINGS_PATH, encoding="utf-8") as f:
            settings = json.load(f).get("settings", {})
    except Exception: pass
    state = {"conversations": {}, "sends": {}, "sent_log": [], "pending": []}
    try:
        with open(STATE_PATH, encoding="utf-8") as f:
            d = json.load(f)
            for k in state: d.setdefault(k, state[k])
            state = d
    except Exception: pass
    return settings, state

def save(state):
    os.makedirs(os.path.dirname(STATE_PATH), exist_ok=True)
    tmp = STATE_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f: json.dump(state, f, ensure_ascii=False, indent=1)
    os.replace(tmp, STATE_PATH)

def gates(settings, state, sender, hard_only=False):
    """Portes : heures + plafond sont dures (même avec --force).
    mode d'envoi et liste blanche sont contournables par --force."""
    today = datetime.now().strftime("%Y-%m-%d")
    hour = datetime.now().hour
    h1 = int(float(settings.get("active_hours_start", 8) or 0))
    h2 = int(float(settings.get("active_hours_end", 21) or 23))
    hours_ok = (h1 <= hour <= h2) if h1 <= h2 else (hour >= h1 or hour <= h2)
    if not hours_ok: return "hors heures actives (%dh-%dh)" % (h1, h2)
    cap = int(float(settings.get("daily_reply_cap", 20) or 20))
    if state.get("sends", {}).get(today, 0) >= cap: return "plafond quotidien atteint (%d)" % cap
    if hard_only: return None
    if settings.get("send_mode", "approbation") != "direct":
        return "mode approbation : passe par une notification (ou --force sur demande explicite de l'utilisateur)"
    wl = [w.strip().lower() for w in (settings.get("whitelist") or "").split(",") if w.strip()]
    if wl and not any(w in sender.lower() for w in wl):
        return "expéditeur hors liste blanche"
    return None

def open_thread(session, sender):
    page = page_read(session)
    if page is None or "messenger.com" not in page.get("url", ""):
        sh(["ob-nav", "--session", session, "--goal", INBOX_URL]); time.sleep(4)
        page = page_read(session)
        if page is None: return None, None
    for e in page.get("elements", []):
        if e.get("role") == "link" and sender.lower() in (e.get("label") or "").lower():
            sh(["ob-page", "--session", session, "click", e["id"]]); time.sleep(4)
            return page_read(session), e["id"]
    return None, None

def send_via_composer(session, text):
    page = page_read(session)
    if page is None: return {"ok": False, "detail": "page illisible avant envoi"}
    vp = page.get("viewport", {})
    w, h = vp.get("width", 1920), vp.get("height", 1080)
    x = SIDEBAR_W + max(200, (w - SIDEBAR_W) // 2)
    for dy in (42, 60, 30):
        y = h - dy
        sh(["ob-vnc", "--session", session, "move", str(x), str(y)])
        sh(["ob-vnc", "--session", session, "click", "1"]); time.sleep(1)
        sh(["ob-vnc", "--session", session, "paste", text]); time.sleep(1)
        sh(["ob-vnc", "--session", session, "key", "return"]); time.sleep(3)
        check = page_read(session)
        if check:
            for e in check.get("elements", []):
                lbl = (e.get("label") or "")
                if e.get("role") == "link" and lbl.strip().startswith("Vous: ") and \
                   text[:30].lower() in lbl.lower():
                    return {"ok": True, "detail": "confirmé dans l'aperçu de la conversation"}
                if "Saisir, Message envoyé à" in lbl and text[:30].lower() in lbl.lower():
                    return {"ok": True, "detail": "confirmé dans le fil"}
        # sinon : le texte est peut-être resté dans le composer — vider avant nouvel essai
        sh(["ob-vnc", "--session", session, "key", "ctrl-a"])
        sh(["ob-vnc", "--session", session, "key", "delete"])
    return {"ok": False, "detail": "envoi non confirmé après 3 essais : vérifier l'écran"}

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--session", required=True)
    ap.add_argument("--to", metavar="NOM")
    ap.add_argument("--text", metavar="TEXTE")
    ap.add_argument("--pending", metavar="ID", help="approuver et envoyer un brouillon en attente")
    ap.add_argument("--force", action="store_true", help="envoi sur demande explicite de l'utilisateur (contourne mode/liste blanche, jamais le plafond)")
    args = ap.parse_args()

    settings, state = load()
    sender, text = args.to, args.text
    pid = None
    if args.pending:
        entry = next((p for p in state["pending"] if p["id"] == args.pending), None)
        if not entry:
            out({"status": "error", "detail": "brouillon introuvable : " + args.pending}, 2)
        sender, text, pid = entry["sender"], entry["text"], entry["id"]
    if not sender or not text:
        out({"status": "error", "detail": "--to et --text requis (ou --pending ID)"}, 2)

    if not args.force:
        block = gates(settings, state, sender)
        if block:
            out({"status": "refused", "reason": block}, 2)
    else:
        block = gates(settings, state, sender, hard_only=True)
        if block:
            out({"status": "refused", "reason": "porte dure (--force ne les contourne pas) : " + block}, 2)

    if not args.force and any(e.get("sender") == sender and e.get("text") == text[:200]
                              for e in state.get("sent_log", [])):
        out({"status": "refused",
             "reason": "réponse identique déjà envoyée à ce destinataire (jamais deux réponses au même message ; --force pour passer)"}, 2)

    thread_page, _ = open_thread(args.session, sender)
    if thread_page is None:
        out({"status": "error", "detail": "conversation introuvable : " + sender}, 2)

    result = send_via_composer(args.session, text)
    if not result["ok"]:
        out({"status": "send_failed", "detail": result["detail"]}, 2)

    today = datetime.now().strftime("%Y-%m-%d")
    state["sends"][today] = state.get("sends", {}).get(today, 0) + 1
    state.setdefault("sent_log", []).append({"ts": datetime.now().isoformat(timespec="seconds"),
                                             "sender": sender, "text": text[:200],
                                             "pending": pid})
    if pid:
        state["pending"] = [p for p in state["pending"] if p["id"] != pid]
    save(state)
    out({"status": "sent", "to": sender, "chars": len(text), "sent_today": state["sends"][today]})

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""ob-plugin-fb-message-guardian-watch — veille scriptée, ZÉRO token au repos.
Conçu pour un cron HYBRIDE (ob-cron --run auto) : le script tourne à chaque passe et
l'agent n'est réveillé QUE si une ligne de sortie commence par [cron-agent].
Toutes les ~3 minutes :
1. résout une session d'écran vivante (config screen_session, sinon auto-détection) ;
2. lance le scan avec un intervalle court ;
3. exécute les actions déterministes LUI-MÊME (notification, envoi modèle, mise en file) ;
4. émet une ligne [cron-agent] SEULEMENT s'il y a du travail IA en attente (await_ai,
   anti-répétition : pas de réveil plus d'une fois par intervalle de scan, sauf nouvelle
   entrée) ou un scan dom_changed (1 diagnostic/jour max). Sinon silence total :
   rien n'est affiché pour l'orchestrateur, aucun token dépensé."""
import argparse, glob, json, os, re, subprocess, sys, time
from datetime import datetime

PLUGIN_ID = "fb-message-guardian"
SCAN_BIN = "/usr/local/bin/ob-plugin-fb-message-guardian-scan"
SEND_BIN = "/usr/local/bin/ob-plugin-fb-message-guardian-send"
SETTINGS_PATH = os.path.expanduser("~/.config/open-bot/plugin-%s.json" % PLUGIN_ID)
STATE_PATH = os.path.expanduser("~/.open-bot/%s/state.json" % PLUGIN_ID)
VNC_DIR = os.path.expanduser("~/.open-bot/vnc")
MARKER = "[cron-agent]"  # ligne reconnue par ob-cron --run auto : réveille l'agent
WAKE_CAP = 3             # réveils max par entrée avant notification « file bloquée »

def pkey_of(msg):
    return (msg or {}).get("pkey") or ""

def open_duplicate(st, sender, pkey):
    """Une entrée OUVERTE existe déjà pour ce même message ? (anti re-comptage pour l'agent)"""
    if not pkey:
        return False
    return any(e.get("status") in ("await_ai", "await_approval") and e.get("sender") == sender
               and e.get("pkey") == pkey for e in st["pending"])

def sh(cmd, timeout=120):
    try:
        return subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        return None

def settings():
    try:
        with open(SETTINGS_PATH, encoding="utf-8") as f:
            return json.load(f).get("settings", {})
    except Exception:
        return {}

def state():
    try:
        with open(STATE_PATH, encoding="utf-8") as f:
            d = json.load(f)
    except Exception:
        d = {}
    d.setdefault("pending", [])
    d.setdefault("watcher", {})
    return d

def save_state(d):
    os.makedirs(os.path.dirname(STATE_PATH), exist_ok=True)
    tmp = STATE_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=1)
    os.replace(tmp, STATE_PATH)

def resolve_session(cfg, st):
    """session fixée en config, sinon la session la plus récente dont la page répond."""
    fixed = (cfg.get("screen_session") or "").strip()
    if fixed:
        return fixed if page_alive(fixed) else None
    st["watcher"].setdefault("session", None)
    remembered = st["watcher"].get("session")
    if remembered and page_alive(remembered):
        return remembered
    candidates = sorted(glob.glob(os.path.join(VNC_DIR, "ses_*")),
                        key=os.path.getmtime, reverse=True)
    for path in candidates[:3]:
        sid = os.path.basename(path)
        if page_alive(sid):
            st["watcher"]["session"] = sid
            save_state(st)
            return sid
    return None

def page_alive(sid):
    p = sh(["ob-page", "--session", sid, "read"], timeout=40)
    return bool(p and p.returncode == 0 and '"url"' in (p.stdout or ""))

def notify(title, body):
    sh(["ob-plugin", "notify", PLUGIN_ID, title, body])

def queue_pending(st, sender, plan, keyword_matched, template_text, pkey=""):
    if open_duplicate(st, sender, pkey):
        return None
    pid = "p-" + os.urandom(2).hex()
    needs_ai = (plan == "send:ai") or (plan == "draft" and not keyword_matched)
    entry = {"id": pid, "sender": sender, "text": "" if needs_ai else template_text,
             "status": "await_ai" if needs_ai else "await_approval",
             "plan": plan, "pkey": pkey, "created": datetime.now().isoformat(timespec="seconds")}
    st["pending"].append(entry)
    save_state(st)
    return entry

def queue_photo_task(st, sender, project, reply, pkey="", quiet=False):
    """Photo à router vers un projet open-bot : tâche pour l'agent (ouvre le fil, sauvegarde)."""
    if open_duplicate(st, sender, pkey):
        return None
    pid = "p-" + os.urandom(2).hex()
    st["pending"].append({"id": pid, "sender": sender, "text": "", "status": "await_ai",
                          "plan": "route_photo", "task": "route_photo", "project": project,
                          "reply": reply or "", "pkey": pkey,
                          "created": datetime.now().isoformat(timespec="seconds")})
    save_state(st)
    if not quiet:
        notify("Photo à router", "%s → projet %s (file %s)" % (sender, project, pid))
    return pid

def act(scan, session, cfg, st):
    done = []
    template = cfg.get("auto_template", "")
    for msg in scan.get("new", []):
        sender = msg["sender"]
        action = msg["action"]
        pkey = pkey_of(msg)
        if action == "notify":
            ntext = msg.get("notify_text")
            if ntext:
                body = (ntext.replace("{expediteur}", sender.split()[0])
                             .replace("{aperçu}", msg.get("preview", "")[:120]))
                if msg.get("route_photo"):
                    body += " — photo à router vers le projet %s" % msg["route_photo"]
            else:
                body = "%s : %s" % (sender, msg["preview"][:120])
            notify("Message Facebook", body)
            done.append("notify:%s" % sender)
        elif action.startswith("send:template"):
            text = (msg.get("text") or template).replace("{expediteur}", sender.split()[0])
            r = sh([SEND_BIN, "--session", session, "--to", sender, "--text", text])
            outj = {}
            try:
                outj = json.loads((r.stdout or "").strip().splitlines()[-1]) if r and r.stdout else {}
            except Exception:
                pass
            if outj.get("status") == "sent":
                done.append("sent:%s" % sender)
            else:
                entry = queue_pending(st, sender, "draft", True, text, pkey)
                if entry:
                    notify("Réponse en attente de ton oui",
                           "Brouillon %s pour %s : « %s » (envoi refusé : %s)"
                           % (entry["id"], sender, text[:80], outj.get("reason", "?")))
                    done.append("queued:%s" % sender)
                else:
                    done.append("dedup:%s" % sender)
        elif action == "send:ai":
            entry = queue_pending(st, sender, "send:ai", False, "", pkey)
            if entry:
                notify("Message Facebook — l'IA prépare une réponse",
                       "%s : %s (file %s)" % (sender, msg["preview"][:100], entry["id"]))
                done.append("ai:%s" % sender)
            else:
                done.append("dedup:%s" % sender)
        elif action == "draft":
            rtext = msg.get("text")
            if rtext:  # réponse fixe d'une règle : brouillon directement approvable
                entry = queue_pending(st, sender, "draft", True, rtext, pkey)
            else:
                entry = queue_pending(st, sender, "draft", bool(msg.get("matched_keyword")), template, pkey)
            if entry:
                if entry["status"] == "await_ai":
                    notify("Message Facebook — l'IA prépare une réponse",
                           "%s : %s (file %s)" % (sender, msg["preview"][:100], entry["id"]))
                else:
                    notify("Réponse en attente de ton oui",
                           "Brouillon %s pour %s : « %s »"
                           % (entry["id"], sender, entry["text"][:80]))
                done.append("queued:%s" % sender)
            else:
                done.append("dedup:%s" % sender)
        if msg.get("route_photo"):  # règle save_photo_to : la photo part vers le projet via l'agent
            if not queue_photo_task(st, sender, msg["route_photo"], msg.get("text", ""), pkey,
                                    quiet=(action == "notify")):
                done.append("dedup:%s" % sender)
            else:
                done.append("photo:%s→%s" % (sender, msg["route_photo"]))
    return done

def pending_ai(st):
    return [p for p in st.get("pending", []) if p.get("status") == "await_ai"]

def wake_agent(st, cfg, session, scan):
    """Porte du cron hybride : imprime [cron-agent] UNIQUEMENT s'il y a du travail.
    - await_ai présents : réveil immédiat à la première entrée, puis au plus une fois
      par intervalle de scan (check_interval_minutes, min 10 min) sauf NOUVELLE entrée ;
      une entrée est réveillée au plus WAKE_CAP fois, ensuite : notification « file
      bloquée » (1/jour) au lieu de réveiller l'agent en boucle.
    - dom_changed : un réveil-diagnostic par jour au maximum.
    - tout le reste : retour sans rien imprimer → passe silencieuse, zéro token."""
    w = st.setdefault("watcher", {})
    ai = pending_ai(st)
    today = datetime.now().strftime("%Y-%m-%d")
    dom_wake = scan.get("status") == "dom_changed" and w.get("last_dom_wake") != today
    wakeable = [e for e in ai if int(e.get("wake_count") or 0) < WAKE_CAP]
    if not ai and not dom_wake:
        return
    if not wakeable and not dom_wake:
        if w.get("stuck_notified_on") != today:
            w["stuck_notified_on"] = today
            senders = ", ".join(sorted({(e.get("sender") or "?").split()[0] for e in ai}))
            notify("File du gardien bloquée",
                   "%d tâche(s) IA non traitée(s) après %d réveils (%s). Vérifie "
                   "ob-plugin-fb-message-guardian-queue --list." % (len(ai), WAKE_CAP, senders))
        return
    try:
        cooldown = max(600.0, float(cfg.get("check_interval_minutes", 15) or 15) * 60.0)
    except (TypeError, ValueError):
        cooldown = 900.0
    fresh = any(not e.get("wake_count") for e in wakeable)
    if not fresh and not dom_wake and (time.time() - float(w.get("last_agent_wake") or 0)) < cooldown:
        return
    w["last_agent_wake"] = time.time()
    if dom_wake:
        w["last_dom_wake"] = today
    for e in wakeable:
        e["wake_count"] = int(e.get("wake_count") or 0) + 1
    save_state(st)
    if ai:
        senders = ", ".join(sorted({(e.get("sender") or "?").split()[0] for e in wakeable}))
        photos = sum(1 for e in wakeable if e.get("task") == "route_photo")
        suffix = " dont %d photo(s) à router vers un projet" % photos if photos else ""
        print("%s Gardien FB : %d tâche(s) IA en attente (%s)%s. Session d'écran : %s."
              % (MARKER, len(wakeable), senders, suffix, session))
    if dom_wake:
        print("%s Gardien FB : scan=dom_changed (plus aucune conversation lisible) sur la "
              "session %s : Facebook a probablement changé son DOM. Diagnostique une fois "
              "avec ob-page --session %s read et répare parse_rows/parse_row du scan si tu "
              "peux, sinon rapporte." % (MARKER, session, session))

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--interval-seconds", type=float, default=180)
    args = ap.parse_args()
    cfg = settings()
    if cfg.get("watcher_enabled", "true") != "true":
        print("watcher désactivé"); return
    st = state()
    session = resolve_session(cfg, st)
    if not session:
        print("aucune session d'écran vivante"); return
    p = sh([SCAN_BIN, "--session", session,
            "--interval-override-seconds", str(args.interval_seconds)])
    if not p or not p.stdout:
        print("scan sans réponse"); return
    try:
        scan = json.loads(p.stdout.strip().splitlines()[-1])
    except Exception:
        print("scan illisible"); return
    st = state()  # recharger : le scan (sous-processus) a pu mettre à jour last_scan/conversations
    status = scan.get("status")
    if status == "too_soon":
        print("rien"); return
    if status == "ok":
        done = act(scan, session, cfg, st)
        ai = pending_ai(st)
        if not done and not ai:
            print("rien"); return
        print("actions: " + (", ".join(done) or "aucune") +
              (" | %d en file IA" % len(ai) if ai else ""))
        wake_agent(st, cfg, session, scan)
        return
    if status == "dom_changed":
        print("scan: dom_changed")
        wake_agent(st, cfg, session, scan)
        return
    print("scan: %s" % status)

if __name__ == "__main__":
    main()
